function canvasTex(w,h,draw,rep){const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');draw(x,w,h);const t=new THREE.CanvasTexture(c);if(rep){t.wrapS=t.wrapT=THREE.RepeatWrapping}return t}
function grime(x,w,h,n,a){for(let i=0;i<n;i++){x.fillStyle='rgba(0,0,0,'+Math.random()*a+')';const r=Math.random()*40+4;x.beginPath();x.arc(Math.random()*w,Math.random()*h,r,0,7);x.fill()}}
