wall:canvasTex(256,256,(x,w,h)=>{x.fillStyle='#4f6150';x.fillRect(0,0,w,h*.55);x.fillStyle='#b7b39a';x.fillRect(0,0,w,h*.45);x.fillStyle='#2e3a2e';x.fillRect(0,h*.45,w,4);grime(x,w,h,90,.12);for(let i=0;i<14;i++){x.strokeStyle='rgba(30,20,10,.35)';x.beginPath();let px=Math.random()*w;x.moveTo(px,h*.3);x.lineTo(px+rnd(-8,8),h);x.stroke()}},1),
