const ANI=renderer.capabilities.getMaxAnisotropy();
function T(w,h,draw){const t=canvasTex(w,h,draw,1);t.anisotropy=ANI;return t}
function nz(x,w,h,a){const id=x.getImageData(0,0,w,h),d=id.data;for(let i=0;i<d.length;i+=4){const n=(Math.random()-.5)*a;d[i]+=n;d[i+1]+=n;d[i+2]+=n}x.putImageData(id,0,0)}
function blot(x,w,h,n,c,r0,r1){for(let i=0;i<n;i++){const cx=Math.random()*w,cy=Math.random()*h,r=rnd(r0,r1),g=x.createRadialGradient(cx,cy,0,cx,cy,r);g.addColorStop(0,c);g.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=g;x.fillRect(cx-r,cy-r,r*2,r*2)}}
function crack(x,w,h,n){for(let i=0;i<n;i++){let px=Math.random()*w,py=Math.random()*h;x.strokeStyle='rgba(25,20,12,'+rnd(.3,.7)+')';x.lineWidth=rnd(.6,1.6);x.beginPath();x.moveTo(px,py);for(let k=0,m=ri(4,12);k<m;k++){px+=rnd(-14,14);py+=rnd(-4,16);x.lineTo(px,py)}x.stroke()}}
function drip(x,w,y0,y1,n,c){for(let i=0;i<n;i++){const px=Math.random()*w,l=rnd(20,y1-y0),g=x.createLinearGradient(0,y0,0,y0+l);g.addColorStop(0,c);g.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=g;x.fillRect(px,y0,rnd(1,4),l)}}
function peel(x,w,h,n,y0,y1,c){for(let i=0;i<n;i++){const cx=rnd(0,w),cy=rnd(y0,y1),r=rnd(6,26);x.fillStyle=c;x.strokeStyle='rgba(40,30,20,.6)';x.lineWidth=1;x.beginPath();for(let a=0;a<6.28;a+=.5){const rr=r*rnd(.5,1.2);x.lineTo(cx+Math.cos(a)*rr,cy+Math.sin(a)*rr*.7)}x.closePath();x.fill();x.stroke()}}
TX.wall=T(512,512,(x,w,h)=>{const s=h*.42;x.fillStyle='#d9d3bb';x.fillRect(0,0,w,s);blot(x,w,s,30,'rgba(150,130,80,.25)',10,60);const g=x.createLinearGradient(0,s,0,h);g.addColorStop(0,'#3f5a46');g.addColorStop(1,'#2a3d30');x.fillStyle=g;x.fillRect(0,s,w,h-s);for(let i=0;i<50;i++){x.fillStyle='rgba(255,255,255,'+rnd(.02,.06)+')';x.fillRect(rnd(0,w),rnd(s,h),rnd(20,80),rnd(1,3))}x.fillStyle='#5a2a1c';x.fillRect(0,s-4,w,6);peel(x,w,h,10,s+10,h-20,'#8d8f84');peel(x,w,h,6,10,s-10,'#a8a594');drip(x,w,0,s,18,'rgba(110,70,30,.35)');drip(x,w,s,h,10,'rgba(20,30,20,.4)');crack(x,w,h,7);blot(x,w,h,25,'rgba(0,0,0,.25)',8,50);const b=x.createLinearGradient(0,h-60,0,h);b.addColorStop(0,'rgba(0,0,0,0)');b.addColorStop(1,'rgba(10,8,4,.7)');x.fillStyle=b;x.fillRect(0,h-60,w,60);nz(x,w,h,18)});
